-- ----------------------------
-- Procedure structure for SearchAllTables
-- ----------------------------
DROP PROCEDURE IF EXISTS `SearchAllTables`;
delimiter ;;
CREATE PROCEDURE `SearchAllTables`(IN search_str VARCHAR(255))
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE tname VARCHAR(64);
    DECLARE cname VARCHAR(64);
    -- 游标：获取当前数据库所有文本类型的列
    DECLARE cur CURSOR FOR
        SELECT TABLE_NAME, COLUMN_NAME
        FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND DATA_TYPE IN ('char', 'varchar', 'text', 'tinytext', 'mediumtext', 'longtext');
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    -- 1. 转义搜索字符串中的单引号（防止 SQL 注入和语法错误）
    SET @search_escaped = REPLACE(search_str, '''', '''''');

    -- 2. 创建临时表存放结果
    DROP TEMPORARY TABLE IF EXISTS temp_results;
    CREATE TEMPORARY TABLE temp_results (
        table_name VARCHAR(64),
        column_name VARCHAR(64),
        matched_row_data TEXT
    );

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO tname, cname;
        IF done THEN
            LEAVE read_loop;
        END IF;

        -- 3. 动态构造查询语句（简化版，直接返回字段值）
        SET @sql = CONCAT(
            'INSERT INTO temp_results (table_name, column_name, matched_row_data) ',
            'SELECT ''', tname, ''', ''', cname, ''', `', cname, '` ',
            'FROM `', tname, '` ',
            'WHERE `', cname, '` LIKE ''%', @search_escaped, '%'' LIMIT 10'
        );

        -- 执行动态 SQL
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END LOOP;

    CLOSE cur;

    -- 4. 输出结果
    SELECT * FROM temp_results;

    -- 5. 清理临时表
    DROP TEMPORARY TABLE temp_results;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
